#!/usr/bin/env pwsh
<#
.SYNOPSIS
	Proves Purview.Telemetry reads a Purview.Unions generated union as a telemetry parameter.

.DESCRIPTION
	Packs Purview.Unions to an isolated feed, then creates a scratch console project for each supported
	target framework that references the packed Purview.Unions package and the locally available
	Purview.Telemetry.SourceGenerator package. The consumer declares:

	  * a union generated by Purview.Unions from a source-visible case list;
	  * a telemetry interface whose method takes that union as a [Tag] parameter.

	The telemetry generator must recognise the union from its source-visible list, emit the union accessor
	against the HasValue/TryGetValue members the unions generator emits, and compile. The test asserts the
	generated accessor calls TryGetValue for the cases, then leak-scans the consumer output for compiler-host
	assemblies.

	This is the real two-generator integration: both generators run in one compilation and neither sees the
	other's output, which is exactly the contract the packages must satisfy.

	The Purview.Telemetry.SourceGenerator package is a prerelease dependency of this gate. It is read from
	LOCAL_NUGET_FEED_PATH (or TELEMETRY_PRERELEASE_FEED); pass -TelemetryFeed when neither is set.

.PARAMETER PackOutput
	Folder that receives the packed Purview.Unions .nupkg. Defaults to artifacts/telemetry-integration.

.PARAMETER TelemetryFeed
	The feed that carries Purview.Telemetry.SourceGenerator. Defaults to LOCAL_NUGET_FEED_PATH, then
	TELEMETRY_PRERELEASE_FEED.

.PARAMETER TelemetryVersion
	The Purview.Telemetry.SourceGenerator version to test. Defaults to 6.0.0.

.PARAMETER Configuration
	The pack/build configuration. Defaults to Release.

.PARAMETER KeepArtifacts
	Leave the scratch consumers and feed in place for inspection.

.EXAMPLE
	./scripts/test-telemetry-integration.ps1

.EXAMPLE
	./scripts/test-telemetry-integration.ps1 -TelemetryFeed p:/_sync-projects/.local-nuget -KeepArtifacts
#>
[CmdletBinding()]
param (
	[string] $PackOutput = (Join-Path (Split-Path -Parent $PSScriptRoot) 'artifacts/telemetry-integration'),
	[string] $TelemetryFeed = $env:LOCAL_NUGET_FEED_PATH,
	[string] $TelemetryVersion = '6.0.0',
	[ValidateSet('Debug', 'Release')]
	[string] $Configuration = 'Release',
	[switch] $KeepArtifacts
)

$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest

if ([string]::IsNullOrWhiteSpace($TelemetryFeed)) {
	$TelemetryFeed = $env:TELEMETRY_PRERELEASE_FEED
}

if ([string]::IsNullOrWhiteSpace($TelemetryFeed)) {
	throw "Purview.Telemetry.SourceGenerator is not on a public feed yet. Set LOCAL_NUGET_FEED_PATH or TELEMETRY_PRERELEASE_FEED, or pass -TelemetryFeed."
}

if (-not (Test-Path -LiteralPath $TelemetryFeed)) {
	throw "The telemetry feed '$TelemetryFeed' does not exist."
}

$telemetryPackage = Get-ChildItem -LiteralPath $TelemetryFeed -Filter "Purview.Telemetry.SourceGenerator.$TelemetryVersion.nupkg" |
	Select-Object -First 1
if ($null -eq $telemetryPackage) {
	throw "The telemetry feed '$TelemetryFeed' does not carry Purview.Telemetry.SourceGenerator $TelemetryVersion."
}

$repositoryRoot = Split-Path -Parent $PSScriptRoot
$version = (Get-Content (Join-Path $repositoryRoot 'package.json') -Raw | ConvertFrom-Json).version
$project = Join-Path $repositoryRoot 'src/src/Unions/Unions.csproj'

$scratch = Join-Path ([System.IO.Path]::GetTempPath()) "unions-telemetry-$([guid]::NewGuid().ToString('N').Substring(0, 8))"
$feed = Join-Path $scratch 'feed'
$failures = [System.Collections.Generic.List[string]]::new()
$originalNuGetPackages = $env:NUGET_PACKAGES

try {
	New-Item -ItemType Directory -Force -Path $feed, $PackOutput | Out-Null

	Write-Host "Packing Purview.Unions $version to $feed..." -ForegroundColor Cyan
	& dotnet pack $project -c $Configuration -o $feed --nologo
	if ($LASTEXITCODE -ne 0) { throw "dotnet pack failed with exit code $LASTEXITCODE." }

	$unionsPackage = Join-Path $feed "Purview.Unions.$version.nupkg"
	if (-not (Test-Path $unionsPackage)) { throw "The packed package '$unionsPackage' was not produced." }

	# NuGet reuses an extracted package for the same id and version. An isolated cache makes each consumer
	# test the package just packed and the telemetry package at the requested version.
	$env:NUGET_PACKAGES = Join-Path $scratch 'packages'

	foreach ($tfm in @('net10.0', 'net11.0')) {
		$consumer = Join-Path $scratch "Consumer.$tfm"
		New-Item -ItemType Directory -Force -Path $consumer | Out-Null

		@"
<?xml version="1.0" encoding="utf-8"?>
<configuration>
	<packageSources>
		<clear />
		<add key="unions" value="$feed" />
		<add key="telemetry" value="$TelemetryFeed" />
	</packageSources>
</configuration>
"@ | Set-Content (Join-Path $consumer 'nuget.config') -Encoding utf8

		@"
<Project Sdk="Microsoft.NET.Sdk">
	<PropertyGroup>
		<OutputType>Exe</OutputType>
		<TargetFramework>$tfm</TargetFramework>
		<LangVersion>latest</LangVersion>
		<Nullable>enable</Nullable>
		<ImplicitUsings>enable</ImplicitUsings>
		<!-- Keep the generated telemetry sources under obj so the compiler does not include them twice. -->
		<EmitCompilerGeneratedFiles>true</EmitCompilerGeneratedFiles>
		<CompilerGeneratedFilesOutputPath>obj/generated</CompilerGeneratedFilesOutputPath>
	</PropertyGroup>
	<ItemGroup>
		<PackageReference Include="Purview.Unions" Version="$version" />
		<PackageReference Include="Purview.Telemetry.SourceGenerator" Version="$TelemetryVersion" />
	</ItemGroup>
	<ItemGroup>
		<!-- The generated telemetry attributes and DI extension use Microsoft.Extensions.* types. The shared
		     framework supplies them without a network package source. -->
		<FrameworkReference Include="Microsoft.AspNetCore.App" />
	</ItemGroup>
</Project>
"@ | Set-Content (Join-Path $consumer 'Consumer.csproj') -Encoding utf8

		@'
using Purview.Telemetry;
using Purview.Unions;

Console.WriteLine("telemetry integration consumer");

[GenerateUnion(typeof(int), typeof(string))]
internal readonly partial struct TelemetryValue;

[ActivitySource("unions-telemetry-integration")]
internal interface ISmokeActivities
{
	[Activity]
	System.Diagnostics.Activity? Run([Tag] TelemetryValue value);
}
'@ | Set-Content (Join-Path $consumer 'Program.cs') -Encoding utf8

		Push-Location $consumer
		try {
			Write-Host "Running the $tfm consumer..." -ForegroundColor Cyan
			& dotnet run -c $Configuration --nologo
			if ($LASTEXITCODE -ne 0) {
				$failures.Add("The $tfm consumer exited with $LASTEXITCODE.")
				continue
			}

			$generatedRoot = Join-Path $consumer 'obj/generated'
			$activitySource = Get-ChildItem $generatedRoot -Recurse -File -Filter '*.Activity.g.cs' |
				Select-Object -First 1
			if ($null -eq $activitySource) {
				$failures.Add("The $tfm consumer produced no telemetry Activity source; the generator did not run.")
				continue
			}

			$generated = Get-Content $activitySource.FullName -Raw
			if ($generated -notmatch 'UnwrapUnion_TelemetryValue' -or $generated -notmatch 'TryGetValue') {
				$failures.Add("The $tfm telemetry accessor did not unwrap TelemetryValue through TryGetValue.")
				continue
			}

			Write-Host "  $tfm passed" -ForegroundColor Green
		}
		finally {
			Pop-Location
		}

		$outputPath = Join-Path $consumer "bin/$Configuration/$tfm"
		if (Test-Path $outputPath) {
			& (Join-Path $PSScriptRoot 'assert-no-compiler-host-assemblies.ps1') -Path $outputPath
			if ($LASTEXITCODE -ne 0) {
				$failures.Add("The $tfm consumer output carries a compiler-host assembly.")
			}
		}
	}
}
catch {
	$failures.Add($_.Exception.Message)
}
finally {
	if ($null -ne $originalNuGetPackages) {
		$env:NUGET_PACKAGES = $originalNuGetPackages
	}
	else {
		Remove-Item Env:NUGET_PACKAGES -ErrorAction SilentlyContinue
	}

	if ($KeepArtifacts) {
		Write-Host "Scratch consumers kept at $scratch" -ForegroundColor Yellow
	}
	else {
		Remove-Item $scratch -Recurse -Force -ErrorAction SilentlyContinue
	}
}

if ($failures.Count -gt 0) {
	foreach ($failure in $failures) {
		if ($env:GITHUB_ACTIONS) { Write-Host "::error::$failure" } else { Write-Host "ERROR: $failure" -ForegroundColor Red }
	}

	exit 1
}

Write-Host 'Every telemetry integration consumer passed.' -ForegroundColor Green
exit 0
